    (N, "Judul: Competitive Strategies and Their Shift to the Future"),
    (B, "Penulis: Helen E. Salavou (Department of Business Administration, Athens University of Economics and Business, Greece)"),
    (B, "Publikasi: European Business Review, Vol. 27 No. 1 (2015), hlm. 80–99"),
